+import { createContext, useContext, useState } from 'react';
+
+const PipelineContext = createContext(null);
+
+export function PipelineProvider({ children, pipelineId }) {
+  const [pipeline, setPipeline] = useState(null);
+  const [candidates, setCandidates] = useState([]);
+
+  useEffect(() => {
+    fetchPipeline(pipelineId).then(setPipeline);
+    fetchCandidates(pipelineId).then(setCandidates);
+  }, [pipelineId]);
+
+  return (
+    <PipelineContext.Provider value={{ pipeline, candidates, setPipeline, setCandidates }}>
+      {children}
+    </PipelineContext.Provider>
+  );
+}
+
+export const usePipeline = () => useContext(PipelineContext);
